contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(address recipient) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(recipient == address(this));
        require(address(c).balance >= 100);

        uint selfBalanceBefore = address(this).balance;
        uint cBalanceBefore = address(c).balance;

        bool firstReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint selfBalanceAfterFirst = address(this).balance;
        uint cBalanceAfterFirst = address(c).balance;

        bool secondReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint selfBalanceAfterSecond = address(this).balance;
        uint cBalanceAfterSecond = address(c).balance;

        assert(!firstReverted
            && selfBalanceAfterFirst == selfBalanceBefore + 100
            && cBalanceBefore - cBalanceAfterFirst == 100
            && secondReverted
            && selfBalanceAfterSecond == selfBalanceAfterFirst
            && cBalanceAfterSecond == cBalanceAfterFirst);
    }
}

