// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address recipient) internal {
        vm.deal(address(c), VALUE_CAP);
        recipient = address(this);
        vm.assume(address(c).balance >= 100);
        uint selfBalanceBefore = address(this).balance;
        uint cBalanceBefore = address(c).balance;
        bool firstReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }
        uint selfBalanceAfterFirst = address(this).balance;
        uint cBalanceAfterFirst = address(c).balance;
        bool secondReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint selfBalanceAfterSecond = address(this).balance;
        uint cBalanceAfterSecond = address(c).balance;
        assertTrue(!firstReverted
            && selfBalanceAfterFirst == selfBalanceBefore + 100
            && cBalanceBefore - cBalanceAfterFirst == 100
            && secondReverted
            && selfBalanceAfterSecond == selfBalanceAfterFirst
            && cBalanceAfterSecond == cBalanceAfterFirst);
    }

    function testFuzz_run(address recipient) public {
        _run(recipient);
    }

    receive() external payable {}
}
